async (page) => {
  const get = async path => { const response = await page.request.get(path); if (!response.ok()) throw new Error(`${path}: ${response.status()}`); return response.json(); };
  const state = await get('/api/state');
  return { state: {season:state.season,week:state.week,phase:state.phase,user_team:state.user_team,save:state.save}, club:await get('/api/club'), roster:await get('/api/roster/team_nexus') };
}
